import tracemalloc

def process_list(n):
    data = [x*x for x in range(n)]
    return sum(x for x in data if x % 2)

def process_gen(n):
    return sum(x*x for x in range(n) if (x*x) % 2)

# Better: single lazy generator, no intermediate at all
def process_gen2(n):
    def squares():
        for x in range(n):
            yield x * x
    return sum(s for s in squares() if s % 2)

for fn in (process_list, process_gen2):
    tracemalloc.start()
    fn(200_000)
    print(fn.__name__, 'peak bytes:', tracemalloc.get_traced_memory()[1])
    tracemalloc.stop()

